INSERT INTO bot_conversations (id, lead_id, company_id, wa_phone, wa_name, direction, message_text, wa_message_id, score_delta, intent, bot_active, created_at) VALUES (1956, '0bde105c-3794-4fc6-941f-900281fb7c22', 'a9575932-01c0-4340-aac1-b47491d1035b', '593969148621', 'Jeferson', 'outbound', 'Con gusto, Saul. A ese valor de $7.000 tenemos opciones como: Aveo/Sail, Picanto, i10 — todos modelos económicos, confiables y perfectos para trabajo de uber. ¿Cuál de estos le llama más la atención o prefiere que le muestre el catálogo completo de vehículos disponibles en ese rango?', NULL, 0, 'info', TRUE, '2026-05-28T20:51:06.034Z');
