INSERT INTO bot_conversations (id, lead_id, company_id, wa_phone, wa_name, direction, message_text, wa_message_id, score_delta, intent, bot_active, created_at) VALUES (1958, '0bde105c-3794-4fc6-941f-900281fb7c22', 'a9575932-01c0-4340-aac1-b47491d1035b', '593969148621', 'Jeferson', 'outbound', 'Excelente pregunta, Saul. El Picanto que manejamos en ese rango de $7.000 es el modelo estándar — muy confiable y económico para trabajo. Si usted prefiere una versión específica (R, automático, etc.), podemos buscarlo personalizado según lo que necesite. ¿Le cotizo el Picanto estándar a $7.000 con la modalidad Mega Estrella que ya eligió?', NULL, 0, 'otro', TRUE, '2026-05-28T20:52:04.608Z');
